source='''from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 6 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0, r1 = min(y for y, x in comp), max(y for y, x in comp)
            c0, c1 = min(x for y, x in comp), max(x for y, x in comp)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            perimeter = {(r0, x) for x in range(c0, c1 + 1)} | {(r1, x) for x in range(c0, c1 + 1)} | {(y, c0) for y in range(r0, r1 + 1)} | {(y, c1) for y in range(r0, r1 + 1)}
            if set(comp) != perimeter:
                continue
            inner = [(y, x) for y in range(r0 + 1, r1) for x in range(c0 + 1, c1)]
            if any(grid[y][x] != 6 for y, x in inner):
                continue
            fill = 7 if len(inner) == 1 else 2
            for y, x in inner:
                out[y][x] = fill
    return out
'''
